-- Run read-only before deployment. Both gates must be true; stop on any mismatch.
SELECT (EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261031000000' AND name='course_shared_lessons' AND cardinality(statements)=1 AND md5(statements[1])='a665d2c1225e027f9356c02628492ba9') AND coalesce((SELECT md5(prosrc)='ae9de477220e2f750834b24517d278cf' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.get_course_outline(uuid)')),false) AND coalesce((SELECT md5(prosrc)='3cf9b8c757bb1e7d3e3eab8ba6aa8f2e' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.get_course_topic(uuid,uuid)')),false) AND coalesce((SELECT md5(prosrc)='9f1251318ac4c5167ccaee3c3d03d5ad' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.save_course_lesson(uuid,uuid,boolean,jsonb,text,bigint,uuid)')),false) AND coalesce((SELECT md5(prosrc)='c81ceeeefda5ab24342df86179f1bd1b' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.resolve_course_video(uuid)')),false) AND to_regclass('public.course_lessons') IS NOT NULL AND to_regclass('public.course_lesson_courses') IS NOT NULL AND to_regclass('public.course_lesson_videos') IS NOT NULL) AS prerequisite_matches, (NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261101000000') AND NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261101010000') AND NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261101020000') AND NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261101030000') AND to_regclass('public.course_outline_entries') IS NULL AND to_regclass('public.course_outline_topics') IS NULL AND NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.courses'::regclass AND attname='outline_revision' AND NOT attisdropped) AND NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.course_videos'::regclass AND attname='metadata_revision' AND NOT attisdropped)) AS package_absent;
SELECT count(*) AS courses FROM public.courses;
SELECT count(*) AS lessons FROM public.course_lessons;
SELECT count(*) AS lesson_bindings FROM public.course_lesson_courses;
SELECT count(*) AS videos FROM public.course_videos;
